items.splice(0,items.length,...items.filter(x=>![7,12].includes(x.id)));
items.forEach(x=>Object.assign(x,window.CONTENT_UPDATES[x.id]||{}));
const $=s=>document.querySelector(s),view=$('#view');let mapMode='all';
const paths={play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',expand:'<path d="M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5"/>',screen:'<rect x="3" y="5" width="18" height="13" rx="1"/><path d="M8 21h8M12 18v3"/>',wall:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3Zm6-3v15m6-12v15"/>',all:'<path d="M4 8a9 5 0 1 1 0 8M4 3v5h5"/><path d="m17 10 3 3-3 3"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="1"/><path d="M16 8V3H3v13h5"/>',tech:'<path d="M4 4h16v16H4Z M8 4v4M12 4v2M16 4v4M4 16h4M4 12h2M4 8h4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.arrow}</svg>`}
function chip(t,l){return `<span class="chip ${t}">${icon(t==='wall'?'wall':t==='screen'?'screen':'all')}${l}</span>`}const chips=chip('screen','ЭКРАНЫ')+chip('wall','СТЕНЫ')+chip('all','360° — ВМЕСТЕ');
const catTitles={'2':'02 / Фоновая ткань','4a':'04А / Колонный зал','4b':'04Б / Альтернативная заставка','5':'05 / Якуты: среда и порталы','9':'09 / Путешествие по мирам','10':'10 / Золотые частицы','11':'11 / Семейный архив'};
function svgMap(){return `<svg class="roomsvg" viewBox="0 0 960 360" role="img" aria-label="Связанная схема трёх стен и сценических экранов. Снизу развёртка стен 11444 на 848 пикселей."><defs><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#182225"/><stop offset="1" stop-color="#0a0e10"/></linearGradient></defs><path d="M100 72 225 25H735L860 72V222H100Z" fill="url(#floor)" stroke="#34444a"/><g data-surface="wall" class="mapzone" role="button" tabindex="0" aria-label="Стены периметра"><path d="M100 72 225 25V81L100 128Z"/><path d="M225 25H735V81H225Z"/><path d="m735 25 125 47v56L735 81Z"/><text x="480" y="59">ЗАДНЯЯ СТЕНА</text><text x="159" y="75" transform="rotate(-20 159 75)">ЛЕВАЯ</text><text x="797" y="75" transform="rotate(20 797 75)">ПРАВАЯ</text></g><path d="M225 82 310 221M735 82 650 221M100 128h760" stroke="#253238" stroke-dasharray="4 6"/><text x="480" y="142" fill="#667c83" text-anchor="middle" font-size="11">ПРОСТРАНСТВО ЗАЛА</text><path d="M480 179v-20m-5 6 5-6 5 6" stroke="#687e85" fill="none"/><g class="mapzone" data-surface="arches" tabindex="0" role="button" aria-label="Полуарочные экраны"><path d="M192 221v-31a32 32 0 0 1 64 0v31Z"/><path d="M704 221v-31a32 32 0 0 1 64 0v31Z"/></g><g class="mapzone" data-surface="vertical" tabindex="0" role="button" aria-label="Вертикальные экраны"><path d="M330 154h28v67h-28ZM363 144h28v77h-28ZM569 144h28v77h-28ZM602 154h28v67h-28Z"/></g><path d="M266 224h428M434 226h92l14 16H420Z" stroke="#5c5140" fill="#221e18"/><text x="480" y="262" fill="#b5a17a" text-anchor="middle" font-size="11">СЦЕНА · ВЕРТИКАЛИ И ПОЛУАРКИ</text><g class="mapzone strip" data-surface="wall" role="button" tabindex="0" aria-label="Развёртка маски стен"><rect x="20" y="283" width="920" height="68.17"/><path d="M327 283v68M633 283v68" stroke-dasharray="4 6"/><text x="480" y="323">РАЗВЁРТКА СТЕН · 11 444 × 848 px · 13,50 : 1</text></g></svg>`}
function map(x){return `<div class="panel mapPanel ${x?'compactMap':''}"><div class="paneltop"><span>ПОВЕРХНОСТИ ${x?' / '+String(x.id).padStart(2,'0'):''}</span></div>${svgMap()}<div class="maptabs"><button data-map="all" class="active" aria-label="Вместе">${icon('all')}Вместе</button><button data-map="wall">${icon('wall')}Стены</button><button data-map="vertical">${icon('screen')}Вертикали</button><button data-map="arches">${icon('screen')}Полуарки</button></div><div class="mapcaption" id="mapCaption">${x?x.mapnote:'Три стены и сценическая зона. Нажмите на группу поверхностей.'}</div><div class="caption">Схема условная. Маска стен: 11 444 × 848 px.<br><a href="#technical">Технические требования ${icon('arrow')}</a></div></div>`}
function rows(){return items.map(x=>`<a class="row" href="#item-${x.id}"><div class="num">${String(x.id).padStart(2,'0')}</div><div><strong>${x.title}</strong><small>${x.qty}${[7,12].includes(x.id)?' · дополнительно':''}</small></div><span>${x.time}</span><span class="surface">${x.status}</span><span class="arrow">${icon('arrow')}</span></a>`).join('')}
const concepts=window.ROOM_CONCEPTS||{};
const concise={
2:{text:'Медно-охристые ткани свисают вдоль стен по всему периметру. Свет проявляет объём складок — от тёмных теней до светло-кремовых бликов. На вертикальных экранах продолжаются полотна; в полуаркax — бордовая глубина, блёстки и логотип.',dynamics:'В начале проходит быстрая волна. Затем ткани плавно колышутся и перетекают, как под лёгким ветром; свет мягко гуляет по складкам. Полотна остаются живыми, объёмными, без статичного рисунка освещения. Тонкие золотистые частицы движутся только внутри проекционного изображения. К концу движение снова ускоряется и бесшовно замыкается в 30-секундный цикл.'},
3:{text:'На экранах — заставки рубрик и локальные титровые акценты. Стены поддерживают их спокойной фоновой анимацией.',waiting:'Ждём примеры контента и ТЗ от команды Урганта.'},
4:{text:'Колонный зал с уходящей в глубину перспективой на трёх стенах. Между колоннами пролетают извивающиеся ткани разной длины. Палитра — рыжеватая охра, медь и тёплые коричневые оттенки; ближние колонны помогают скрывать швы проекции.',dynamics:'Ткани медленно проплывают между рядами колонн, сохраняя глубину и спокойный ритм фона.'},
5:{text:'Объёмная панорама объединяет три стены и сценические экраны в одну среду. Номер развивается в двух частях: ритуальная степь с волнами под бубен сменяется оживающими якутскими зарисовками в дымчатых облаках. Визуал поддерживает исполнителей и ритм номера.',waiting:'Уточняем музыку, точки переходов, длительность номера и набор сюжетных зарисовок.'},
6:{waiting:'Ждём материалы герба и требования к отображению от event-агентства.'},
7:{waiting:'Ждём детали номера и ТЗ.'},
8:{waiting:'Ждём сценарий выноса торта и музыку.'},
9:{text:'По задумке — объёмная пространственная композиция: из знакомой тканевой заставки раскрывается мир, по которому зритель путешествует вместе с камерой. Глубина, смена локаций и масштабов создают погружение; историю ведёт закадровый голос. Основной визуальный рил ниже показывает предполагаемый характер изображения.',dynamics:'Раскрытие ткани → путешествие по объёмным мирам → переход в интро №2. Конкретные сцены, маршрут камеры, темп и визуальные акценты разработаем по написанному тексту и сценарию.',waiting:'Текст и сценарий ещё ожидаются. После их получения адаптируем историю в визуальное решение и раскадровку.'},
10:{text:'Основа номера — абстрактная композиция на чёрном фоне: летящие частицы образуют потоки, волны и завихрения. Движение то замедляется, то ускоряется, частицы вытягиваются в тонкие линии; местами возникает эффект полёта сквозь поток. Проекция следует музыке и поддерживает артистов со световыми шарами.',dynamics:'Плавное течение → завихрение → ускорение и линии → полёт сквозь частицы → замедление. Изредка из потока формируется узнаваемый образ, ненадолго сохраняется и снова распадается. Ориентир — около восьми фигур за весь номер; точное количество и моменты появления определим по музыке и постановке. Палитра: шампань, сливочный, светло-жёлтый, охра и медь.',waiting:'Ждём музыку, рисунок номера и перечень символических образов.'},
11:{text:'Личная история Ирины и мужа из фото и видео разных лет. Кадры располагаются в объёме, на нескольких планах и внутри пространственных форм. Основа — современное чёрно-белое кино без искусственного состаривания.',dynamics:'Композиция меняется по музыке: то фото и видео заполняют всё пространство, то собираются в отдельные плоские экраны, медленно летящие в объёме на разной глубине. На каждом экране развивается своя оживающая зарисовка из жизни. Фотографии оживают, видео сменяется по музыке. Отдельные кадры и детали ненадолго обретают цвет и снова возвращаются в чёрно-белую основу — герои раскрашивают свою судьбу.',waiting:'Получить у Ирины фото и видео разных лет с телефона, песню и текст. Отобрать эпизоды, нарезать историю и собрать сценарий.'},
12:{waiting:'Ждём меню, порядок подачи и ТЗ на шесть лупов.'}
};
function conceptCard(c){return `<figure class="roomConcept"><button class="imagebutton" data-image="${c.src}" aria-label="Увеличить визуализацию зала"><img src="${c.src}" alt="${c.title}"><span>${icon('expand')}</span></button><figcaption><span>${c.title}</span><small>${c.label||'ВИЗУАЛЬНЫЙ ЭСКИЗ'}</small></figcaption>${c.reason?`<p class="conceptReason">${c.reason}</p>`:''}</figure>`}
function galleryCard(n){const r=window.LOCAL_REFS[n];if(!r)return '';return `<figure class="referenceTile"><div class="referenceImage">${r.kind==='video'?`<div class="videoPlayer"><video data-media-src="${r.src}" poster="${r.poster}" playsinline preload="none" aria-label="${r.title}"></video><button class="videoStart" data-video-start aria-label="Воспроизвести: ${r.title}">${icon('play')}</button><span class="videoStatus" role="status"></span></div>`:`<button class="imagebutton" data-image="${r.src}" aria-label="Увеличить: ${r.title}"><img src="${r.src}" loading="lazy" alt="${r.title}"><span>${icon('expand')}</span></button>`}</div><figcaption><span>${r.title}</span>${r.reason?`<p class="referenceReason">${r.reason}</p>`:""}</figcaption></figure>`}
function overview(){const cs=[concepts[2],concepts[4],{src:"assets/approved/yakutia-dark-clean.png",title:"№5 · Номер якутов · Истории в дымке",label:"ВЫБРАННЫЙ ВИЗУАЛ"},concepts[10].objects[0]];return `<section><div class="eyebrow">Orion Hall / видеомэппинг / версия 03</div><div class="titlebar"><h1>Дорога<br>к сердцу<span style="color:var(--gold)">.</span></h1><div class="edition">3 стены + экраны<strong>360°</strong></div></div><p class="intro">Ткань раскрывает мир.<br>Пространство становится частью истории.</p><div class="sectionhead"><h2>Примеры визуализации некоторых сцен</h2></div><div class="overviewVisuals">${cs.length?cs.map(conceptCard).join(''):[13,6].map(galleryCard).join('')}</div><div class="sectionhead"><h2>Контент</h2><span>Нумерация сметы сохранена</span></div><div class="rows">${rows()}</div><div class="sectionhead"><h2>Площадка</h2><a href="#technical">Технические требования ${icon('arrow')}</a></div><div class="venueRow"><button class="imagebutton" data-image="assets/hall.jpg" aria-label="Увеличить модель зала"><img src="assets/hall.jpg" alt="Модель зала"><span>${icon('expand')}</span></button><button class="imagebutton" data-image="assets/stage.jpg" aria-label="Увеличить сцену"><img src="assets/stage.jpg" alt="Сценическая зона"><span>${icon('expand')}</span></button></div></section>`}
function yakutStory(c){return `<div class="storyBlock"><h2>Часть 1 · Степь и энергетические волны</h2><p>Вступление: спокойная степь с длинной перспективой и ощущением большого пространства. Анимация сдержанная, чтобы сохранить внимание на ритуале и исполнителях.</p><p>Под удары бубна по пейзажу расходятся широкие полупрозрачные воздушно-энергетические волны. Их прохождение создаёт движение внутри картинки: попробуем лёгкое вздрагивание изображения, колыхание травы и редкую пыль, подхваченную импульсом. Эффект проверим на анимационном тесте.</p></div>${conceptCard(c)}<div class="storyBlock"><h3>Переход во вторую часть</h3><p>Волны постепенно размягчаются и превращаются в дымку. Степь растворяется в общем фоне, а из дымчатых областей начинают проявляться первые сюжетные образы.</p><h2>Часть 2 · Якутские истории в облаках</h2><p>Во время номера по периметру происходит постепенное визуальное прорисовывание: то тут, то там вспыхивают и раскрываются крупные облака с якутскими сюжетными зарисовками. Внутри — природа Якутии, люди, быт, шаманы и ритуалы. Мягкие размытые края связывают сцены с общей средой; образы проявляются, оживают и вновь уходят в дымку.</p><p>Основа — бесшовный луп продолжительностью 1,5 минуты. Он повторяется на протяжении всей оставшейся длины номера. Истории появляются в разных местах и с разным ритмом, чтобы повтор сохранял интерес и ощущение живого пространства.</p></div><div class="additionalConcepts">${c.additional.map(conceptCard).join('')}</div><div class="storyBlock"><h3>Завершение · Возвращение в степь</h3><p>По команде выхода сюжетные облака растворяются, дымка рассеивается, и зал возвращается в степь из первой части. Точку выхода и переход согласуем с музыкой и постановкой.</p></div>`}
function particleStory(c){return `${conceptCard(c)}<div class="storyBlock"><h2>Ускорение · Полёт сквозь частицы</h2><p>Поток набирает скорость, точки вытягиваются в тонкие летящие линии. Перспектива и движение создают ощущение пролёта внутри частиц; затем скорость снижается, и линии снова рассыпаются на отдельные точки.</p></div>${conceptCard(c.additional[0])}<div class="storyBlock"><h2>Редкие смысловые акценты · Формирование фигур</h2><p>Периодически из абстрактного движения собираются символы из жизни юбиляра. Ориентировочно восемь образов за номер: каждый появляется ненадолго и возвращается в общий поток. Ниже — два примера таких акцентов.</p></div><div class="additionalConcepts">${c.objects.map(conceptCard).join('')}</div>`}
function detail(x){const idx=items.indexOf(x),t=concise[x.id],c=concepts[x.id],refs=x.local;return `<section><div class="eyebrow">${String(x.id).padStart(2,'0')} / ${x.qty} / ${x.time}</div><h1 class="detailTitle">${x.title}</h1>${t.text?`<p class="formatLead">${t.text.replace('полуаркax','полуарках')}</p>`:''}<div class="formatLayout"><div class="formatVisual">${x.id===5?yakutStory(c):x.id===10?particleStory(c):c?conceptCard(c):refs.length?`<div class="primaryReference">${galleryCard(refs[0])}</div>`:`<div class="waitingVisual"><span class="eyebrow">${String(x.id).padStart(2,'0')}</span><h2>Материалы ожидаются</h2><p>${t.waiting}</p></div>`}${![5,10].includes(x.id)&&c?.additional?.length?`<div class="additionalConcepts">${c.additional.map(conceptCard).join('')}</div>`:''}${t.dynamics?`<p class="dynamics"><strong>Динамика видео.</strong> ${t.dynamics}</p>`:''}${x.id===4?`<div class="scopeProposal"><h3>Предложение по объёму</h3><p>Сделать акцент на этом формате и создать одну качественную заставку с колонным залом. Вторую отдельную заставку не производить: при такой детализации двух вариантов выйдем за бюджет.</p><p>Для фонового оформления использовать также <a href="#item-2">заставку главного зала 360°</a>.</p><small>В смете предусмотрены две заставки. Это предложение по перераспределению объёма для согласования.</small></div>`:''}${refs.length?`<div class="referenceHeading">Референсы</div><div class="referenceGallery">${(c?refs:refs.slice(1)).map(galleryCard).join('')}</div>`:''}${t.waiting&&refs.length||t.waiting&&c?`<p class="waitingText">${t.waiting}</p>`:''}</div><div class="formatMap">${map(x)}</div></div><div class="pager"><a href="${idx?'#item-'+items[idx-1].id:'#overview'}">${icon('left')}${idx?'Предыдущий формат':'Обзор'}</a><a href="${idx<items.length-1?'#item-'+items[idx+1].id:'#overview'}">${idx<items.length-1?'Следующий формат':'Обзор'}${icon('right')}</a></div></section>`}
function technical(){return `<section><div class="eyebrow">Производство / технические требования</div><h1>Поверхности<br>и форматы<span style="color:var(--gold)">.</span></h1><p>Подтверждённые параметры и то, что ещё необходимо получить от технической команды.</p><div class="techHero"><span>МАСКА СТЕН / ОБЩАЯ РАЗВЁРТКА</span><strong>11 444 × 848 <small>px</small></strong><p>Ширина × высота · пропорция 13,50 : 1</p></div>${map()}<div class="split" style="margin-top:25px"><div class="panel"><h2>Стены зала</h2><dl><dt>Поверхности</dt><dd>3 стены, единая развёртка</dd><dt>Маска</dt><dd>11 444 × 848 px</dd><dt>Деление по стенам</dt><dd>Ждём границы и техническую карту</dd><dt>Стыки и перекрытия</dt><dd>Уточняются с технической командой</dd></dl></div><div class="panel"><h2>Сценические экраны</h2><dl><dt>Группы</dt><dd>Вертикальные полотна и полуарки</dd><dt>Разрешения и маски</dt><dd>Ожидаются</dd><dt>Точные размеры и раскладка</dt><dd>Ожидаются</dd><dt>Роль в композиции</dt><dd>Согласованная часть общего визуала</dd></dl></div></div><div class="sectionhead"><h2>До финального рендера</h2></div><div class="tasklist">${['Получить исходный файл маски и границы всех поверхностей.','Подтвердить FPS, кодек, контейнер, цветовое пространство и требования медиасервера.','Уточнить порядок файлов, синхронизацию, старт, луп и выход по команде.','Проверить швы, яркость, перспективу и читаемость на площадке.'].map((t,n)=>`<div><span>0${n+1}</span><p>${t}</p></div>`).join('')}</div><div class="note"><strong>Исходники и апскейл</strong><br>Для цельного кадра важна пропорция 13,50 : 1, а не только обозначение «4K» или «8K». Например, исходник шириной 7 680 px всё равно уже итоговой маски 11 444 px. Планируем панорамные среды, локальные сюжетные окна и тест апскейла на деталях. Финальный файл — точно по технической карте; увеличение разрешения само по себе не восстанавливает недостающие детали.</div><div class="sectionhead"><h2>Площадка</h2></div><div class="mediaGrid"><article class="mediaCard"><button class="imagebutton" data-image="assets/hall.jpg"><img src="assets/hall.jpg" alt="Модель зала"></button></article><article class="mediaCard"><button class="imagebutton" data-image="assets/stage.jpg"><img src="assets/stage.jpg" alt="Схема сцены"></button></article></div></section>`}
function render(){document.querySelectorAll('video').forEach(v=>v.pause());const h=location.hash||'#overview',x=items.find(x=>h==='#item-'+x.id);view.innerHTML=h==='#technical'?technical():x?detail(x):overview();$('#nav').innerHTML=`<a href="#overview" class="${!x&&h!=='#technical'?'active':''}">${icon('all')}Пространство и контент</a><a href="#technical" class="${h==='#technical'?'active':''}">${icon('tech')}Технические требования</a>${items.map(i=>`<a href="#item-${i.id}" class="${x===i?'active':''}"><small>${String(i.id).padStart(2,'0')}</small>${i.short}</a>`).join('')}`;bind(x);window.scrollTo(0,0)}
function bind(x){bindVideoPlayers();document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{const d=$('#lightbox'),im=d.querySelector('img');im.src=b.dataset.image;im.alt=b.querySelector('img')?.alt||'Визуальный референс';d.showModal()});function setMap(mode){mapMode=mode;document.querySelectorAll('[data-surface]').forEach(g=>g.classList.toggle('dimmed',mode!=='all'&&g.dataset.surface!==mode));document.querySelectorAll('[data-map]').forEach(b=>b.classList.toggle('active',b.dataset.map===mode));const c=$('#mapCaption');c.innerHTML=mode==='all'?(x?x.mapnote:'Вся система: три стены + сценические экраны.'):mode==='wall'?(x?x.wall:'Три стены зала. Общая маска 11 444 × 848 px.'):mode==='vertical'?(x?x.screen:'Вертикальные сценические полотна. Точные маски ожидаются.'):'Полуарочные экраны. '+(x?.id===2?'Красно-бордовый фон, мягкие блёстки и логотип.':x?x.screen:'Часть согласованной сценической композиции.')}document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>setMap(b.dataset.map));document.querySelectorAll('[data-surface]').forEach(g=>{g.onclick=()=>setMap(g.dataset.surface);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setMap(g.dataset.surface)}}});document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()})))}
$('#present').innerHTML=icon('expand')+'Режим показа';$('#present').onclick=()=>{const on=document.body.classList.toggle('presentation');$('#present').innerHTML=icon('expand')+(on?'Выйти из показа':'Режим показа')};document.querySelectorAll('dialog .close').forEach(b=>{b.innerHTML=icon('close');b.onclick=()=>b.closest('dialog').close()});document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('close',()=>{if(d.id==='embedDialog')d.querySelector('.embedframe').innerHTML=''})});window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(!document.body.classList.contains('presentation')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const pages=['#overview','#technical',...items.map(x=>'#item-'+x.id)];let i=pages.indexOf(location.hash||'#overview');if(e.key==='ArrowRight')location.hash=pages[Math.min(i+1,pages.length-1)];if(e.key==='ArrowLeft')location.hash=pages[Math.max(i-1,0)]});render();
